let temperatures = [20, 25, 30, 35, 40];

let fahrenheit = temperatures.map(c => (c * 9/5) + 32);
console.log(fahrenheit); // [68, 77, 86, 95, 104]

let orders = [
    { id: 1, amount: 150, status: "completed" },
    { id: 2, amount: 200, status: "pending" },
    { id: 3, amount: 50, status: "completed" },
    { id: 4, amount: 300, status: "cancelled" },
    { id: 5, amount: 100, status: "completed" }
];

let totalCompleted = orders
    .filter(o => o.status === "completed")
    .map(o => o.amount)
    .reduce((sum, amount) => sum + amount, 0);

console.log(`Сумма завершённых: ${totalCompleted}`); // 300
